-- Table structure for t_accp
-- ----------------------------
DROP TABLE IF EXISTS `t_accp`;
CREATE TABLE `t_accp`  (
  `autoId` int NOT NULL AUTO_INCREMENT,
  `accpId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'id主键',
  `createdOn` datetime NOT NULL COMMENT '创建时间',
  `createdBy` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建用户',
  `ownerUser` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属用户',
  `ownerDepartment` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '所属部门',
  `modifiedOn` datetime NULL DEFAULT NULL COMMENT '最近修改时间',
  `modifiedBy` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改用户',
  `isDeleted` tinyint NULL DEFAULT 0,
  `c_sbmc` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '设备名称',
  `c_gg` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '规格',
  `c_wxsj` datetime NULL DEFAULT NULL COMMENT '保养时间',
  `c_wxry` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '保养人员',
  `c_lxfs` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '联系方式',
  `c_pjyxh` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配件预消耗',
  `c_qs` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '权属',
  `c_bz` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`autoId`) USING BTREE,
  UNIQUE INDEX `Accp_accpId`(`accpId` ASC) USING BTREE,
  INDEX `Accp_isDeleted`(`ownerUser` ASC) USING BTREE,
  INDEX `Accp_ownerUser`(`ownerDepartment` ASC) USING BTREE,
  INDEX `Accp_ownerDepartment`(`isDeleted` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '设备保养计划表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_accp
-- ----------------------------

-- ----------------------------
-- Table structure for t_app_management
-- ----------------------------
DROP TABLE IF EXISTS `t_app_management`;
CREATE TABLE `t_app_management`  (
  `autoId` int NOT NULL AUTO_INCREMENT,
  `appManagementId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'id主键',
  `createdOn` datetime NOT NULL COMMENT '创建时间',
  `createdBy` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建用户',
  `modifiedOn` datetime NULL DEFAULT NULL COMMENT '最近修改时间',
  `modifiedBy` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改用户',
  `isDeleted` tinyint NULL DEFAULT 0,
  `appName` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '应用名称',
  `appAbbr` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '应用唯一缩写',
  `startingCode` int NULL DEFAULT NULL COMMENT '起始编码',
  `entityNumber` int NULL DEFAULT NULL COMMENT '实体数量',
  `installPassword` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '安装密码',
  `remarks` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '备注',
  `iconConfig` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '图标配置',
  `isInstalled` tinyint NULL DEFAULT NULL COMMENT '是否安装',
