  UNIQUE INDEX `AppManage_appManageId`(`appManagementId` ASC) USING BTREE,
  INDEX `AppManage_isDeleted`(`isDeleted` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '应用管理' ROW_FORMAT = DYNAMIC;

