-- ----------------------------
-- Table structure for t_approval_config
-- ----------------------------
DROP TABLE IF EXISTS `t_approval_config`;
CREATE TABLE `t_approval_config`  (
  `autoId` int NOT NULL AUTO_INCREMENT,
  `approvalConfigId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程配置id',
  `approvalFlowId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '最新的流程定义id',
  `entityCode` mediumint NOT NULL DEFAULT 0 COMMENT '实体Code',
  `flowName` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程名称',
  `runningTotal` int NOT NULL DEFAULT 0 COMMENT '运行中的流程统计',
  `completeTotal` int NOT NULL DEFAULT 0 COMMENT '结束的流程统计',
  `isDisabled` tinyint NULL DEFAULT 0 COMMENT '是否禁用',
  `isDeleted` tinyint NULL DEFAULT 0 COMMENT '是否删除',
  `createdBy` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建用户',
  `createdOn` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `modifiedBy` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改用户',
  `modifiedOn` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最近修改时间',
  `wfProcDefId` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'wf定义Id',
  `flowType` tinyint NULL DEFAULT 1 COMMENT '工作流类型',
  `configTag` varchar(300) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '配置标签',
  `appAbbr` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '所属应用',
  PRIMARY KEY (`autoId`) USING BTREE,
  UNIQUE INDEX `approvalConfigId`(`approvalConfigId` ASC) USING BTREE,
  INDEX `entityCode`(`entityCode` ASC) USING BTREE,
  INDEX `flowId`(`approvalFlowId` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 48 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '审批配置' ROW_FORMAT = DYNAMIC;

