  `approvalConfigId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审批流程id',
  `flowDefinition` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '流程定义json',
  `createdOn` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
