  UNIQUE INDEX `approvalFlowId`(`approvalFlowId` ASC) USING BTREE,
  INDEX `approvalConfigId`(`approvalConfigId` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 41 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '审批流程' ROW_FORMAT = DYNAMIC;

