-- ----------------------------
-- Table structure for t_approval_history
-- ----------------------------
DROP TABLE IF EXISTS `t_approval_history`;
CREATE TABLE `t_approval_history`  (
  `autoId` int NOT NULL AUTO_INCREMENT,
  `approvalHistoryId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程任务id',
  `approvalTaskId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '审批流程id',
  `approver` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批人',
  `stepName` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '步骤名称',
  `currentNode` smallint NOT NULL DEFAULT 0 COMMENT '步骤节点',
  `nodeType` smallint NOT NULL DEFAULT 1 COMMENT '节点类型',
  `remark` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批注',
  `isBacked` tinyint NULL DEFAULT 0 COMMENT '是否驳回',
  `approvalOn` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '审批时间',
  `attrMore` varchar(700) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '扩展属性 (JSON Map)',
  `createdBy` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '创建用户',
  `createdOn` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `modifiedBy` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '修改用户',
  `modifiedOn` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '最近修改时间',
