-- Table structure for t_approval_task
-- ----------------------------
DROP TABLE IF EXISTS `t_approval_task`;
CREATE TABLE `t_approval_task`  (
  `autoId` int NOT NULL AUTO_INCREMENT,
  `approvalTaskId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程任务id',
  `approvalFlowId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批流程id',
  `approvalConfigId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '审批流程id',
  `approvalStatus` tinyint NOT NULL DEFAULT 0 COMMENT '审核状态',
  `entityId` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '关联实体ID',
  `currentNode` smallint NOT NULL DEFAULT 0 COMMENT '步骤节点',
  `signType` smallint NOT NULL DEFAULT 2 COMMENT '审核类型',
  `stepName` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '步骤名称',
  `approvalUser` char(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '最近审批人',
  `approvalOn` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '审批时间',
  `remark` varchar(600) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '批注',
  `attrMore` json NULL COMMENT '扩展属性 (JSON Map)',
