nt-size: 16px; /* 序列号字体大小 */\\\\n  color: #ff6600; /* 序列号颜色 */\\\\n  margin: 10px 0; /* 序列号与上下内容的间隔 */\\\\n}\\\\n\\\\n/* 卡片状态样式 */\\\\n.card-status {\\\\n  font-size: 12px; /* 状态字体大小 */\\\\n  color: #ffffff; /* 状态颜色 */\\\\n  background-color: #007bff; /* 状态背景颜色 */\\\\n  padding: 2px 8px; /* 状态内边距 */\\\\n  border-radius: 4px; /* 状态圆角 */\\\\n  margin-top: 10px; /* 状态与内容的间隔 */\\\\n}\\\\n\\\\n/* 卡片操作按钮样式 */\\\\n.card-actions button {\\\\n  margin-top: 10px; /* 按钮与内容的间隔 */\\\\n  padding: 5px 10px; /* 按钮内边距 */\\\\n  border: none; /* 按钮无边框 */\\\\n  border-radius: 4px; /* 按钮圆角 */\\\\n  cursor: pointer; /* 鼠标悬停时显示手型 */\\\\n}\\\\n\\\\n/* 编辑按钮样式 */\\\\n.edit-btn {\\\\n  background-color: #28a745; /* 编辑按钮背景颜色 */\\\\n  color: #ffffff; /* 编辑按钮文字颜色 */\\\\n}\\\\n\\\\n/* 详情按钮样式 */\\\\n.details-btn {\\\\n  background-color: #007bff; /* 详情按钮背景颜色 */\\\\n  color: #ffffff; /* 详情按钮文字颜色 */\\\\n}\\\\n\\\\n/* 删除按钮样式 */\\\\n.delete-btn {\\\\n  background-color: #dc3545; /* 删除按钮背景颜色 */\\\\n  color: #ffffff; /* 删除按钮文字颜色 */\\\\n}\",\"customClass\":[\"card-container\"],\"functions\":\"\",\"layoutType\":\"PC\",\"jsonVersion\":3,\"dataSources\":[],\"onFormCreated\":\"\",\"onFormMounted\":\"\",\"onAfterSetFormData\":\"\",\"onFormDataChange\":\"\",\"onFormValidate\":\"\"}}\'\nWHERE `formLayoutId` = \'0000008-425d56e2f69a4d1fb8fca3e581f9a2a0\'', 'FormLayout', 'FormLayout');
