me\":\"\",\"label\":\"设备状态\",\"labelAlign\":\"\",\"placeholder\":\"\",\"columnWidth\":\"200px\",\"size\":\"\",\"labelWidth\":null,\"labelHidden\":false,\"labelWrap\":false,\"disabled\":false,\"hidden\":false,\"clearable\":true,\"filterable\":false,\"allowCreate\":false,\"remote\":false,\"automaticDropdown\":false,\"multiple\":false,\"multipleLimit\":0,\"collapseTags\":false,\"dsEnabled\":false,\"dsName\":\"\",\"dataSetName\":\"\",\"firstOptionAsDefault\":false,\"labelKey\":\"label\",\"valueKey\":\"value\",\"optionValueType\":\"\",\"optionItems\":[{\"value\":1,\"label\":\"正常\",\"displayOrder\":0},{\"value\":2,\"label\":\"故障\",\"displayOrder\":1}],\"required\":false,\"requiredHint\":\"\",\"validation\":\"\",\"validationHint\":\"\",\"customClass\":\"\",\"labelIconClass\":null,\"labelIconPosition\":\"rear\",\"labelTooltip\":null,\"onCreated\":\"\",\"onMounted\":\"\",\"onRemoteQuery\":\"\",\"onChange\":\"\",\"onFocus\":\"\",\"onBlur\":\"\",\"onValidate\":\"\"},\"nameReadonly\":true,\"optionItemsReadonly\":true,\"id\":\"select89724\"}],\"options\":{\"name\":\"gridCol48348\",\"hidden\":false,\"span\":12,\"offset\":0,\"push\":0,\"pull\":0,\"responsive\":true,\"md\":12,\"sm\":12,\"xs\":24,\"customClass\":\"\"},\"id\":\"grid-col-48348\"},{\"type\":\"grid-col\",\"category\":\"container\",\"icon\":\"grid-col\",\"internal\":true,\"widgetList\":[{\"type\":\"picture-upload\",\"icon\":\"picture-upload-field\",\"formItemFlag\":true,\"options\":{\"name\":\"img\",\"keyNameEnabled\":false,\"keyName\":\"\",\"label\":\"图片\",\"labelAlign\":\"\",\"labelWidth\":null,\"labelHidden\":false,\"columnWidth\":\"200px\",\"disabled\":false,\"hidden\":false,\"required\":false,\"requiredHint\":\"\",\"customRule\":\"\",\"customRuleHint\":\"\",\"uploadURL\":\"DSV[\'uploadServer\'] + \'/picture/upload\'\",\"uploadTip\":\"\",\"withCredentials\":true,\"multipleSelect\":false,\"showFileList\":true,\"limit\":1,\"fileMaxSize\":5,\"fileTypes\":[\"jpeg\",\"png\",\"gif\"],\"customClass\":\"\",\"labelIconClass\":null,\"labelIconPosition\":\"rear\",\"labelTooltip\":null,\"onCreated\":\"\",\"onMounted\":\"\",\"onBeforeUpload\":\"\",\"onUploadSuccess\":\"\",\"onUploadError\":\"\",\"onFileRemove\":\"\",\"onValidate\":\"\"},\"nameReadonly\":true,\"id\":\"pictureupload65473\"}],\"options\":{\"name\":\"gridCol105999\",\"hidden\":false,\"span\":12,\"offset\":0,\"push\":0,\"pull\":0,\"responsive\":true,\"md\":12,\"sm\":12,\"xs\":24,\"customClass\":\"\"},\"id\":\"grid-col-105999\"}],\"options\":{\"name\":\"grid35474\",\"hidden\":false,\"gutter\":12,\"colHeight\":null,\"customClass\":\"\"},\"id\":\"grid35474\"}],\"formConfig\":{\"modelName\":\"formData\",\"refName\":\"vForm\",\"rulesName\":\"rules\",\"labelWidth\":60,\"labelPosition\":\"left\",\"h5LabelTop\":true,\"mobileLabelPosition\":\"top\",\"gridResponsive\":true,\"size\":\"\",\"labelAlign\":\"label-left-align\",\"mobileLabelAlign\":\"label-left-align\",\"dashboardGridRowHeight\":48,\"cssCode\":\"/* 卡片容器样式 */\\r\\n        .card-container {\\r\\n            display: flex;\\r\\n            flex-wrap: wrap;\\r\\n            padding: 20px;\\r\\n            gap: 20px; /* 添加卡片之间的间隔 */\\r\\n            justify-content: center; /* 使卡片居中 */\\r\\n            background-color: #000000; /* 背景颜色设置为黑色 */\\r\\n            color: #ffffff; /* 文字颜色设置为白色 */\\r\\n        }\\r\\n\\r\\n        /* 单个卡片样式 */\\r\\n        .card {\\r\\n            background-color: #003366; /* 卡片背景颜色设置为深蓝色 */\\r\\n            border-radius: 12px; /* 卡片圆角增大 */\\r\\n            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2); /* 卡片阴影增大 */\\r\\n            width: calc(33.333% - 20px); /* 卡片宽度，占据容器的三分之一减去间隔 */\\r\\n            padding: 20px; /* 调整为更合理的内边距 */\\r\\n            display: flex;\\r\\n            flex-direction: column;\\r\\n            align-items: center;\\r\\n            justify-content: space-between;\\r\\n            transition: transform 0.3s ease-in-out; /* 添加动画效果 */\\r\\n        }\\r\\n\\r\\n        .card:hover {\\r\\n            transform: scale(1.05); /* 鼠标悬停时放大卡片 */\\r\\n        }\\r\\n\\r\\n        /* 卡片标题样式 */\\r\\n        .card-title {\\r\\n            font-size: 20px; /* 标题字体大小增大 */\\r\\n            font-weight: bold; /* 标题字体加粗 */\\r\\n            color: #00aaff; /* 标题颜色设置为亮蓝色 */\\r\\n            margin-bottom: 15px; /* 标题与内容之间的间隔增大 */\\r\\n        }\\r\\n\\r\\n        /* 卡片内容样式 */\\r\\n        .card-content {\\r\\n            font-size: 16px; /* 内容字体大小增大 */\\r\\n            color: #ffffff; /* 内容颜色设置为白色 */\\r\\n            text-align: center; /* 文本居中 */\\r\\n            margin-bottom: 15px; /* 内容与序列号之间的间隔增大 */\\r\\n        }\\r\\n\\r\\n        /* 卡片序列号样式 */\\r\\n        .card-serial-number {\\r\\n            font-size: 18px; /* 序列号字体大小增大 */\\r\\n            color: #00aaff; /* 序列号颜色设置为亮蓝色 */\\r\\n            margin: 15px 0; /* 序列号与上下内容的间隔增大 */\\r\\n        }\\r\\n\\r\\n        /* 卡片状态样式 */\\r\\n        .card-status {\\r\\n            font-size: 14px; /* 状态字体大小 */\\r\\n            color: #ffffff; /* 状态颜色设置为白色 */\\r\\n            background-color: #005588; /* 状态背景颜色设置为深蓝色 */\\r\\n            padding: 4px 12px; /* 状态内边距增大 */\\r\\n            border-radius: 6px; /* 状态圆角增大 */\\r\\n            margin-top: 15px; /* 状态与内容的间隔增大 */\\r\\n        }\\r\\n\\r\\n        /* 卡片操作按钮样式 */\\r\\n        .card-actions button {\\r\\n            margin: 5px; /* 按钮之间的间隔 */\\r\\n            padding: 8px 16px; /* 按钮内边距增大 */\\r\\n            border: none; /* 按钮无边框 */\\r\\n            border-radius: 6px; /* 按钮圆角增大 */\\r\\n            cursor: pointer; /* 鼠标悬停时显示手型 */\\r\\n            font-size: 14px; /* 按钮字体大小 */\\r\\n            transition: background-color 0.3s ease-in-out; /* 添加动画效果 */\\r\\n        }\\r\\n\\r\\n        .card-actions button:hover {\\r\\n            filter: brightness(1.2); /* 鼠标悬停时增加亮度 */\\r\\n        }\\r\\n\\r\\n        /* 编辑按钮样式 */\\r\\n        .edit-btn {\\r\\n            background-color: #00aaff; /* 编辑按钮背景颜色设置为亮蓝色 */\\r\\n            color: #ffffff; /* 编辑按钮文字颜色设置为白色 */\\r\\n        }\\r\\n\\r\\n        /* 详情按钮样式 */\\r\\n        .details-btn {\\r\\n            background-color: #005588; /* 详情按钮背景颜色设置为深蓝色 */\\r\\n            color: #ffffff; /* 详情按钮文字颜色设置为白色 */\\r\\n        }\\r\\n\\r\\n        /* 删除按钮样式 */\\r\\n        .delete-btn {\\r\\n            background-color: #ff5555; /* 删除按钮背景颜色设置为红色 */\\r\\n            color: #ffffff; /* 删除按钮文字颜色设置为白色 */\\r\\n        }\",\"customClass\":[\"card-container\"],\"functions\":\"\",\"layoutType\":\"PC\",\"jsonVersion\":3,\"dataSources\":[],\"onFormCreated\":\"\",\"onFormMounted\":\"\",\"onAfterSetFormData\":\"\",\"onFormDataChange\":\"\",\"onFormValidate\":\"\"}}', 'ALL');
