INSERT INTO `t_renwu` VALUES (23, '0001197-de458159a824410bb950d2b3b3b9009a', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', 0, '“绿色能源小镇建设”', '0001196-1faf4713c7a9402c94576ab4d5d77c7b', '“绿色能源小镇建设”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '在特定区域打造一个以可再生能源为主要能源供应的小镇，包括太阳能、风能、水能等的综合利用，建设配套的能源存储和传输设施，实现能源自给自足和低碳排放。');
INSERT INTO `t_renwu` VALUES (24, '0001197-012758b5460b4fcebd336ef75a972827', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', 0, '“智能医疗辅助诊断系统开发”', '0001196-f80e6d63be15465db04240322e06ad3b', '“智能医疗辅助诊断系统开发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '利用人工智能和大数据技术，开发一套能够辅助医生进行疾病诊断的系统，通过对大量医疗数据的学习和分析，提供准确的诊断建议和治疗方案。');
INSERT INTO `t_renwu` VALUES (25, '0001197-f74b373dbb084a31ada0649153b816ba', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', 0, '“乡村振兴旅游发展计划”', '0001196-7e70e37d0e6e44458088da5509e2fb92', '“乡村振兴旅游发展计划”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '对特定乡村地区进行旅游资源开发和规划，建设旅游基础设施，打造特色旅游产品，促进乡村经济发展和农民增收。');
INSERT INTO `t_renwu` VALUES (26, '0001197-4f2ed3611e87482399b993764f8ee85d', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', 0, '“城市交通拥堵缓解方案”', '0001196-9458ab58085f43c083290f08b0c1eb22', '“城市交通拥堵缓解方案”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '通过优化交通信号灯设置、增加公共交通线路和设施、建设智能交通管理系统等措施，缓解城市交通拥堵状况，提高交通运输效率。');
INSERT INTO `t_renwu` VALUES (27, '0001197-74108a3d6a3d4998812f21add63d6ff9', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', 0, '“在线教育平台优化与拓展”', '0001196-f67a72e9a15242b7b047c827fead7648', '“在线教育平台优化与拓展”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '对现有的在线教育平台进行功能优化，增加课程种类和教学资源，提升用户体验，扩大用户群体。');
INSERT INTO `t_renwu` VALUES (28, '0001197-3fa18b45c08f46d08438eeabb07e5500', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', 0, '“环保新材料研发与应用”', '0001196-bce5bd584b0646bb98a3266a015e591a', '“环保新材料研发与应用”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '研发具有环保性能的新型材料，如可降解塑料、高性能环保涂料等，并推动其在相关行业的广泛应用。');
INSERT INTO `t_renwu` VALUES (29, '0001197-cfb92164dd29451aa4a678490899fcec', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', 0, '“农产品电商供应链整合”', '0001196-73c4856ce0594e1581c4fd45a83295f0', '“农产品电商供应链整合”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '建立农产品从产地到消费者的一站式电商供应链，包括农产品采购、仓储、物流配送和销售等环节的整合与优化。');
INSERT INTO `t_renwu` VALUES (30, '0001197-25c35b428f294aac9ad5bebc7f67e65d', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', 0, '“智能健身设备研发”', '0001196-37155b32297c466aa6fedd63aad587e8', '“智能健身设备研发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '研发一系列结合智能技术的健身设备，如智能跑步机、智能健身单车等，能够实时监测用户运动数据并提供个性化的健身方案。');
INSERT INTO `t_renwu` VALUES (31, '0001197-11aa7c489d5941908e65b24665ade317', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', 0, '“文化遗产数字化保护”', '0001196-d53faaa0e0554a09abc2264cf830219a', '“文化遗产数字化保护”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '运用数字化技术对文化遗产进行采集、存储、展示和保护，让更多人能够了解和欣赏珍贵的文化遗产。');
INSERT INTO `t_renwu` VALUES (32, '0001197-0abc6446a55043b4b2684bc6a9c12d6c', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:30', '0000021-00000000000000000000000000000001', 0, '“社区养老服务中心建设”', '0001196-fbb09022c11744d380cabebe9016864c', '“社区养老服务中心建设”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '在社区内建设养老服务中心，提供医疗护理、康复保健、文化娱乐等综合性养老服务，满足老年人的生活需求。');
INSERT INTO `t_renwu` VALUES (33, '0001197-453c97e9955644cb9d3cc5f8cb14ba4b', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“工业废水处理技术改进”', '0001196-de6ff990faf2453d99975c9ed8c907ff', '“工业废水处理技术改进”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '研发和应用更高效的工业废水处理技术，降低废水排放对环境的污染，实现水资源的循环利用。');
INSERT INTO `t_renwu` VALUES (34, '0001197-206d730fe7544e1aa9dc30788121f06b', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“虚拟现实教育游戏开发”', '0001196-cce627a9f6a74b6ba07e39746c239dd7', '“虚拟现实教育游戏开发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '开发以教育为主题的虚拟现实游戏，让学生在沉浸式的体验中学习知识，提高学习兴趣和效果。');
INSERT INTO `t_renwu` VALUES (35, '0001197-6be498e4c9bb4f5b959980a87593b458', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“智慧农业监控系统搭建”', '0001196-e9a323817cde47f1a0a048dc5277c2fa', '“智慧农业监控系统搭建”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '利用物联网技术搭建智慧农业监控系统，实现对农田的土壤湿度、温度、病虫害等信息的实时监测和精准管理。');
INSERT INTO `t_renwu` VALUES (36, '0001197-936442c93f4e43a4882ef729ec774196', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“新能源汽车充电桩网络布局”', '0001196-e18a788b975241cd8d80a737d5697cad', '“新能源汽车充电桩网络布局”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '在城市和高速公路沿线合理布局新能源汽车充电桩，解决新能源汽车充电难的问题，促进新能源汽车的推广应用。');
INSERT INTO `t_renwu` VALUES (37, '0001197-5eff2d48631d4e339701f5200c0290f8', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“跨境电商物流优化方案”', '0001196-a9f3378944124a6694e8dc7b87bea348', '“跨境电商物流优化方案”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '针对跨境电商业务，优化物流流程，降低物流成本，提高物流效率和服务质量。');
INSERT INTO `t_renwu` VALUES (38, '0001197-9b57901645914d63b230589afe8c9adb', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“智能家居安防系统研发”', '0001196-3d870688e267402691dc38c456b372d2', '“智能家居安防系统研发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '研发一套具备智能监控、入侵报警、火灾预警等功能的智能家居安防系统，保障家庭安全。');
INSERT INTO `t_renwu` VALUES (39, '0001197-5f5eb6c057e846ebba7bfab3c66a5705', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“医疗大数据分析平台建设”', '0001196-c82ab02c7b23424298aea4e3a83d1dc7', '“医疗大数据分析平台建设”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '建立医疗大数据分析平台，对海量医疗数据进行深度挖掘和分析，为医疗决策、疾病预防和治疗提供支持。');
INSERT INTO `t_renwu` VALUES (40, '0001197-66004f7fd9924d3db2ceba9e14fdce3b', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“无人超市运营模式探索”', '0001196-8c90d2317bb441d097ae3182b1e32f46', '“无人超市运营模式探索”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '探索无人超市的运营模式和技术方案，实现超市的无人化经营，提高运营效率和顾客购物体验。');
INSERT INTO `t_renwu` VALUES (41, '0001197-05ed629ea27b4fa3a7a97762713fe3aa', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“城市公园生态修复工程”', '0001196-df288a6227a34ef78f31d59f4d0d8b5e', '“城市公园生态修复工程”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '对城市公园的生态环境进行修复和改善，增加植被覆盖，优化水体质量，打造生态友好型城市公园。');
INSERT INTO `t_renwu` VALUES (42, '0001197-45a43eb4ed71423b9cafb4effa5284da', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“个性化定制服装生产项目”', '0001196-2ef802b2a4b44c8bbbe05c6d934fee49', '“个性化定制服装生产项目”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '利用数字化技术实现服装的个性化定制生产，满足消费者对服装款式、尺寸和风格的个性化需求。');
INSERT INTO `t_renwu` VALUES (43, '0001197-316fadf8068c4b7a8f8a579eee2fa59e', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“智能物流仓储管理系统开发”', '0001196-00f5df710e3e482990020ba80ef37cf7', '“智能物流仓储管理系统开发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '开发一套智能物流仓储管理系统，实现货物的自动化存储、检索和管理，提高仓储空间利用率和作业效率。');
INSERT INTO `t_renwu` VALUES (44, '0001197-a314bab2fdaa453e9aeef4d6ba8048cc', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“农村电商人才培训计划”', '0001196-22dd6b9101364cd78c0903c67b43abf4', '“农村电商人才培训计划”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '针对农村地区开展电商人才培训，提高农民的电商运营能力，推动农村电商发展。');
INSERT INTO `t_renwu` VALUES (45, '0001197-151074793c9b4e5ab2fe5d9b875edb6e', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“太阳能光伏发电站建设”', '0001196-98002f73c1dc41a297ab1a9bdeaf9f11', '“太阳能光伏发电站建设”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '在合适的地区建设太阳能光伏发电站，将太阳能转化为电能，并入电网供应。');
INSERT INTO `t_renwu` VALUES (46, '0001197-0777caabbf9e40a281dbfb96c9acc930', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:31', '0000021-00000000000000000000000000000001', 0, '“智能语音助手应用拓展”', '0001196-2126ba80db094cab8f007f2115b5ff70', '“智能语音助手应用拓展”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '拓展智能语音助手的应用场景，如智能家居控制、办公辅助、车载系统等，提供更加便捷的人机交互方式。');
INSERT INTO `t_renwu` VALUES (47, '0001197-338044a1e6e347e8867262e974002ee4', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“海洋牧场建设与运营”', '0001196-26b484a37bdb46acb9faab6eb3fc788b', '“海洋牧场建设与运营”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '在海洋特定区域建设海洋牧场，进行海洋生物养殖和增殖，实现海洋渔业的可持续发展。');
INSERT INTO `t_renwu` VALUES (48, '0001197-0c9f885c1bc644cd84359495a0d1269a', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“金融科技风险防控系统研发”', '0001196-c14dd0eb6f1b4d9aac7c5ff3dcb7098d', '“金融科技风险防控系统研发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '研发针对金融科技领域的风险防控系统，有效识别和防范金融创新带来的各类风险。');
INSERT INTO `t_renwu` VALUES (49, '0001197-1e1a948731c94c87bd70ea6b8096509a', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“智能垃圾分类与回收系统”', '0001196-21f1676031e94ba3aa4398659b68faaa', '“智能垃圾分类与回收系统”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '建立一套智能垃圾分类与回收系统，通过传感器和数据分析实现垃圾分类的自动化和精准化。');
INSERT INTO `t_renwu` VALUES (50, '0001197-e0ab262640b849b18f0c8ed6606f0b14', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“3D 打印医疗器械研发”', '0001196-094379ef1a714b708aed6a667d990234', '“3D 打印医疗器械研发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '利用 3D 打印技术研发个性化的医疗器械，如假肢、牙齿矫正器等，提高医疗效果和患者舒适度。');
INSERT INTO `t_renwu` VALUES (51, '0001197-6d81c96f667c4f20bb7c488795e32e50', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“特色农产品品牌塑造”', '0001196-a0f25504ea9747dfa5a2ef48e238df18', '“特色农产品品牌塑造”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '对具有地域特色的农产品进行品牌策划和推广，提升农产品的附加值和市场竞争力。');
INSERT INTO `t_renwu` VALUES (52, '0001197-924c19a444d941bd97b1407fcdbf64fa', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“智慧校园综合管理平台搭建”', '0001196-7531830e573145d2a77dfef4a7e9050b', '“智慧校园综合管理平台搭建”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '搭建智慧校园综合管理平台，实现教学管理、学生管理、后勤管理等的信息化和智能化。');
INSERT INTO `t_renwu` VALUES (53, '0001197-bbfe72e4869d46588d718f167f8c0b42', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“工业机器人研发与应用”', '0001196-8dee2d7afc9141aa88c25aaa0b1afc4c', '“工业机器人研发与应用”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '研发高性能的工业机器人，并推动其在制造业中的广泛应用，提高生产效率和产品质量。');
INSERT INTO `t_renwu` VALUES (54, '0001197-1a920352e99a4dd99375f7bbadf35664', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“基因编辑技术治疗疾病研究”', '0001196-f9ea6680bf0d4f68b94b01197bc93d34', '“基因编辑技术治疗疾病研究”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '开展基因编辑技术在疾病治疗方面的研究，探索治疗遗传疾病和疑难杂症的新方法。');
INSERT INTO `t_renwu` VALUES (55, '0001197-07cdf85b9c904a3a8591c8aeaecd3452', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“农村饮水安全提升工程”', '0001196-02fd214fc9074ce58fe5f9b4cfb24776', '“农村饮水安全提升工程”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '对农村地区的饮水设施进行改造和升级，确保农村居民能够用上安全、清洁的饮用水。');
INSERT INTO `t_renwu` VALUES (56, '0001197-ff5e06919f99405484064a469bb8cc58', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“无人配送机器人研发”', '0001196-849e0b10c0b04403add8772cf28090c8', '“无人配送机器人研发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '研发能够自主导航和送货的无人配送机器人，应用于快递、外卖等配送场景。');
INSERT INTO `t_renwu` VALUES (57, '0001197-e2a32685ff0643e592343a42ffa6b747', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“城市地下综合管廊建设”', '0001196-9f5e5795c93f42a589ec68ddd54acdc8', '“城市地下综合管廊建设”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '在城市地下建设综合管廊，集中铺设电力、通信、给排水等各类管线，提高城市基础设施的管理和维护效率。');
INSERT INTO `t_renwu` VALUES (58, '0001197-a44596bfef5d4479b43f52ff387c340d', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“量子通信技术应用试点”', '0001196-b37ead8f674a41e1bdc216fb6c740914', '“量子通信技术应用试点”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '开展量子通信技术在特定领域的应用试点，如金融、政务等，保障信息传输的安全性。');
INSERT INTO `t_renwu` VALUES (59, '0001197-da116e9db6d242f0986fcf81eb2bd9f8', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:32', '0000021-00000000000000000000000000000001', 0, '“中医药现代化研发项目”', '0001196-5f5ff477fa75482eae2a94d1b4b5f1b4', '“中医药现代化研发项目”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '运用现代科学技术对中医药进行研究和开发，提高中医药的疗效和质量控制水平。');
INSERT INTO `t_renwu` VALUES (60, '0001197-3380a9fb82224d7592f94d03be7fb64f', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', 0, '“航空航天零部件制造工艺改进”', '0001196-6fc9a9d1a5b24ebfb31fda9bb21be89b', '“航空航天零部件制造工艺改进”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '改进航空航天零部件的制造工艺，提高零部件的精度和可靠性，满足航空航天领域的高要求。');
INSERT INTO `t_renwu` VALUES (61, '0001197-e8b35e57b5f5400fa25d289c649dbc10', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', 0, '“智慧工厂建设方案”', '0001196-3e0bf7737b1e40388da69e395050a399', '“智慧工厂建设方案”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '打造智能化的工厂，实现生产设备的互联互通、生产过程的自动化控制和智能化管理。');
INSERT INTO `t_renwu` VALUES (62, '0001197-8309c19053d845adab9c34ff4eced84f', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', 0, '“可穿戴健康监测设备研发”', '0001196-8525fae3412b4ef297db335124bf1d53', '“可穿戴健康监测设备研发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '研发具有多种健康监测功能的可穿戴设备，如心率监测、血压监测、睡眠监测等，为用户提供实时的健康数据。');
INSERT INTO `t_renwu` VALUES (63, '0001197-f8b9aa9e58484390baab4680d27be0d6', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', 0, '“文化创意产业园建设”', '0001196-1a88d847d616467a9a295573ce1de62d', '“文化创意产业园建设”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '建设文化创意产业园，吸引文化创意企业入驻，形成产业集聚效应，推动文化创意产业发展。');
INSERT INTO `t_renwu` VALUES (64, '0001197-2f222454616a46bd978e807e542cd6f4', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', 0, '“冷链物流配送优化”', '0001196-6b42a434a41849fb996917f8ee89222a', '“冷链物流配送优化”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '优化冷链物流的配送流程和技术，确保生鲜食品、药品等在运输过程中的温度控制和质量安全。');
INSERT INTO `t_renwu` VALUES (65, '0001197-cb132ce184e648928cbb39c1f9c0216e', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', 0, '“智慧水务管理系统开发”', '0001196-876c749d7d064c6b95621bc194938352', '“智慧水务管理系统开发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '开发智慧水务管理系统，实现对水资源的监测、调度和管理的智能化，提高水资源利用效率。');
INSERT INTO `t_renwu` VALUES (66, '0001197-26f7169671a54bc8b69daea4bbc039d3', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 15:24:33', '0000021-00000000000000000000000000000001', 0, '“高性能电池材料研发”', '0001196-3587b1df80444da18e11a3dd1c901884', '“高性能电池材料研发”', '0000021-4ad8495b30304b4b944afcbf748d982a', '2024-07-04', '2024-08-31', '研发具有更高性能的电池材料，如锂离子电池正极材料、负极材料等，提升电池的能量密度和循环寿命。');
