INSERT INTO `t_ribao` VALUES (1, '0001210-c803f15c90da4e0480632f0228e5518d', '2024-07-18 14:56:26', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:56:26', '0000021-00000000000000000000000000000001', 1, '2024-07-01', '0000021-00000000000000000000000000000001', '1', NULL, '1', '1', '1');
INSERT INTO `t_ribao` VALUES (2, '0001210-1023cead8c2c4cc1aa0c5e069f6b2056', '2024-07-18 14:59:03', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:59:03', '0000021-00000000000000000000000000000001', 0, '2023-07-20', '0000021-00000000000000000000000000000001', '完成了项目报告的初稿撰写。', NULL, '对项目报告进行修改完善，与团队成员讨论并收集反馈。', '在收集数据时遇到部分数据缺失，需要同事帮忙提供相关数据源。', '在撰写报告过程中，深刻体会到提前规划框架的重要性，能让思路更清晰，提高工作效率。');
INSERT INTO `t_ribao` VALUES (3, '0001210-ac0d0bb707004c769bf97671847ebc4d', '2024-07-18 14:59:03', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:59:03', '0000021-00000000000000000000000000000001', 0, '2023-07-21', '0000021-00000000000000000000000000000001', '处理了客户的投诉，并协调相关部门给出解决方案。', NULL, '跟进客户对解决方案的满意度，准备新客户的资料。', '与其他部门沟通协调时存在信息不对称，希望能建立更有效的沟通机制。', '面对客户投诉要保持耐心和积极的态度，解决问题的同时也是提升自身能力的机会。');
INSERT INTO `t_ribao` VALUES (4, '0001210-ea51e3788f554995bbcd58dd7bc4491a', '2024-07-18 14:59:03', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:59:03', '0000021-00000000000000000000000000000001', 0, '2023-07-22', '0000021-00000000000000000000000000000001', '完成本月销售数据的统计和分析。', NULL, '根据分析结果制定下个月的销售策略。', '分析过程中发现部分数据不准确，耗费了较多时间核对，希望能优化数据录入流程。', '数据准确是分析的基础，工作中任何环节都要严谨认真。');
INSERT INTO `t_ribao` VALUES (5, '0001210-29eb9489faa9444e98bb88b1a210fe13', '2024-07-18 14:59:03', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:59:03', '0000021-00000000000000000000000000000001', 0, '2023-07-23', '0000021-00000000000000000000000000000001', '组织了部门内部的培训活动。', NULL, '整理培训反馈，制定后续的培训计划。', '培训场地的设备临时出现故障，影响了培训效果，需要技术部门定期维护设备。', '培训不仅能提升团队能力，也能增进团队成员之间的交流和合作。');
INSERT INTO `t_ribao` VALUES (6, '0001210-0b77a93e9e3b45fb8ecca9e26da34d09', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', 0, '2023-07-24', '0000021-00000000000000000000000000000001', '完成网站页面的初步设计。', NULL, '与开发团队对接，进行页面的开发工作。', '设计需求变更频繁，导致工作进度受阻，需要与上级明确最终需求。', '在工作中要及时沟通需求变更，避免不必要的返工。');
INSERT INTO `t_ribao` VALUES (7, '0001210-a3194e96dbca4a2999568a8e975bdfa9', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', 0, '2023-07-25', '0000021-00000000000000000000000000000001', '对新产品进行了市场调研。', NULL, '撰写调研报告，向领导汇报调研结果。', '调研样本的代表性不足，需要扩大调研范围，希望能获得更多的调研资源。', '市场调研要全面、深入，才能为产品决策提供有力支持。');
INSERT INTO `t_ribao` VALUES (8, '0001210-e20beb692e274fefa3372f37135eab63', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', 0, '2023-07-26', '0000021-00000000000000000000000000000001', '优化了生产流程，提高了生产效率。', NULL, '持续监控生产流程的运行情况，进行必要的调整。', '部分员工对新流程不熟悉，需要加强培训和指导。', '创新和优化是推动工作进步的关键，但也要关注实施过程中的问题和人员的适应情况。');
INSERT INTO `t_ribao` VALUES (9, '0001210-5d7dd3947963409dbab1ae8a47a24495', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', 0, '2023-07-27', '0000021-00000000000000000000000000000001', '参加了行业会议，收集了最新的行业信息。', NULL, '整理会议资料，在部门内部分享。', '会议时间紧凑，无法深入了解某些关键信息，希望能有更多时间与专家交流。', '参加行业会议能开阔视野，及时了解行业动态，对工作有很大的启发。');
INSERT INTO `t_ribao` VALUES (10, '0001210-fc0becda0b19422ab7e56ea7d503e307', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', 0, '2023-07-28', '0000021-00000000000000000000000000000001', '完成了财务报表的编制。', NULL, '进行财务审计的准备工作。', '在数据核对时出现了一些误差，花费了较多时间查找原因，需要提高数据处理的准确性。', '财务工作要求高度的细心和责任心，任何小的错误都可能带来严重后果。');
INSERT INTO `t_ribao` VALUES (11, '0001210-eb39e7f99cff4a9a8faf956e262c35db', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-18 14:59:04', '0000021-00000000000000000000000000000001', 0, '2023-07-29', '0000021-00000000000000000000000000000001', '协助同事完成了项目的部分任务。', NULL, '独立负责自己项目的推进工作。', '在协助过程中对同事的项目不够熟悉，需要更多的前期沟通和了解。', '团队合作中相互支持和帮助能促进项目的顺利进行，也能增进同事之间的关系。');
