INSERT INTO `t_xiangmu` VALUES (21, '0001196-1faf4713c7a9402c94576ab4d5d77c7b', '2024-07-11 14:43:57', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:57', '0000021-00000000000000000000000000000001', 0, NULL, '“绿色能源小镇建设”', '0000021-00000000000000000000000000000001', '在特定区域打造一个以可再生能源为主要能源供应的小镇，包括太阳能、风能、水能等的综合利用，建设配套的能源存储和传输设施，实现能源自给自足和低碳排放。', '0001199-98656814b7ce4d318333c1cdb41242da');
INSERT INTO `t_xiangmu` VALUES (22, '0001196-f80e6d63be15465db04240322e06ad3b', '2024-07-11 14:43:57', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:57', '0000021-00000000000000000000000000000001', 0, NULL, '“智能医疗辅助诊断系统开发”', '0000021-00000000000000000000000000000001', '利用人工智能和大数据技术，开发一套能够辅助医生进行疾病诊断的系统，通过对大量医疗数据的学习和分析，提供准确的诊断建议和治疗方案。', '0001199-aca42f855e0f4a3a8373d9086e4f7d6b');
INSERT INTO `t_xiangmu` VALUES (23, '0001196-7e70e37d0e6e44458088da5509e2fb92', '2024-07-11 14:43:57', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:57', '0000021-00000000000000000000000000000001', 0, NULL, '“乡村振兴旅游发展计划”', '0000021-00000000000000000000000000000001', '对特定乡村地区进行旅游资源开发和规划，建设旅游基础设施，打造特色旅游产品，促进乡村经济发展和农民增收。', '0001199-e122145d4669414395aa12004eae9863');
INSERT INTO `t_xiangmu` VALUES (24, '0001196-9458ab58085f43c083290f08b0c1eb22', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', 0, NULL, '“城市交通拥堵缓解方案”', '0000021-00000000000000000000000000000001', '通过优化交通信号灯设置、增加公共交通线路和设施、建设智能交通管理系统等措施，缓解城市交通拥堵状况，提高交通运输效率。', '0001199-20d220e828c046ad952961b081e7865d');
INSERT INTO `t_xiangmu` VALUES (25, '0001196-f67a72e9a15242b7b047c827fead7648', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', 0, NULL, '“在线教育平台优化与拓展”', '0000021-00000000000000000000000000000001', '对现有的在线教育平台进行功能优化，增加课程种类和教学资源，提升用户体验，扩大用户群体。', '0001199-fb4841db0fee4b889a86e9c3d10da344');
INSERT INTO `t_xiangmu` VALUES (26, '0001196-bce5bd584b0646bb98a3266a015e591a', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', 0, NULL, '“环保新材料研发与应用”', '0000021-00000000000000000000000000000001', '研发具有环保性能的新型材料，如可降解塑料、高性能环保涂料等，并推动其在相关行业的广泛应用。', '0001199-89de4e874d034307b82eda6137b9cdef');
INSERT INTO `t_xiangmu` VALUES (27, '0001196-73c4856ce0594e1581c4fd45a83295f0', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', 0, NULL, '“农产品电商供应链整合”', '0000021-00000000000000000000000000000001', '建立农产品从产地到消费者的一站式电商供应链，包括农产品采购、仓储、物流配送和销售等环节的整合与优化。', '0001199-a49a85da8c9042739b79c703eca0cbdd');
INSERT INTO `t_xiangmu` VALUES (28, '0001196-37155b32297c466aa6fedd63aad587e8', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', 0, NULL, '“智能健身设备研发”', '0000021-00000000000000000000000000000001', '研发一系列结合智能技术的健身设备，如智能跑步机、智能健身单车等，能够实时监测用户运动数据并提供个性化的健身方案。', '0001199-3872a121129f42f897de752acedea996');
INSERT INTO `t_xiangmu` VALUES (29, '0001196-d53faaa0e0554a09abc2264cf830219a', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', 0, NULL, '“文化遗产数字化保护”', '0000021-00000000000000000000000000000001', '运用数字化技术对文化遗产进行采集、存储、展示和保护，让更多人能够了解和欣赏珍贵的文化遗产。', '0001199-4de8331d25b74af699068cd943d1270c');
INSERT INTO `t_xiangmu` VALUES (30, '0001196-fbb09022c11744d380cabebe9016864c', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', 0, NULL, '“社区养老服务中心建设”', '0000021-00000000000000000000000000000001', '在社区内建设养老服务中心，提供医疗护理、康复保健、文化娱乐等综合性养老服务，满足老年人的生活需求。', '0001199-9a4417c5b9ea4f9a848a981b3df7a124');
INSERT INTO `t_xiangmu` VALUES (31, '0001196-de6ff990faf2453d99975c9ed8c907ff', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', 0, NULL, '“工业废水处理技术改进”', '0000021-00000000000000000000000000000001', '研发和应用更高效的工业废水处理技术，降低废水排放对环境的污染，实现水资源的循环利用。', '0001199-ecdec978734a444eae3d08a9a958f1fb');
INSERT INTO `t_xiangmu` VALUES (32, '0001196-cce627a9f6a74b6ba07e39746c239dd7', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', 0, NULL, '“虚拟现实教育游戏开发”', '0000021-00000000000000000000000000000001', '开发以教育为主题的虚拟现实游戏，让学生在沉浸式的体验中学习知识，提高学习兴趣和效果。', '0001199-b9ed3a0ecbcc491b8b816f76891b8fc0');
INSERT INTO `t_xiangmu` VALUES (33, '0001196-e9a323817cde47f1a0a048dc5277c2fa', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:58', '0000021-00000000000000000000000000000001', 0, NULL, '“智慧农业监控系统搭建”', '0000021-00000000000000000000000000000001', '利用物联网技术搭建智慧农业监控系统，实现对农田的土壤湿度、温度、病虫害等信息的实时监测和精准管理。', '0001199-164cc0f2b0cf44aab10d20b3fb49ef8f');
INSERT INTO `t_xiangmu` VALUES (34, '0001196-e18a788b975241cd8d80a737d5697cad', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', 0, NULL, '“新能源汽车充电桩网络布局”', '0000021-00000000000000000000000000000001', '在城市和高速公路沿线合理布局新能源汽车充电桩，解决新能源汽车充电难的问题，促进新能源汽车的推广应用。', '0001199-5d4d0176718346f1a7743714be14021e');
INSERT INTO `t_xiangmu` VALUES (35, '0001196-a9f3378944124a6694e8dc7b87bea348', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', 0, NULL, '“跨境电商物流优化方案”', '0000021-00000000000000000000000000000001', '针对跨境电商业务，优化物流流程，降低物流成本，提高物流效率和服务质量。', '0001199-e341bf4de78a42879ed8f13a435d69da');
INSERT INTO `t_xiangmu` VALUES (36, '0001196-3d870688e267402691dc38c456b372d2', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', 0, NULL, '“智能家居安防系统研发”', '0000021-00000000000000000000000000000001', '研发一套具备智能监控、入侵报警、火灾预警等功能的智能家居安防系统，保障家庭安全。', '0001199-9c031adc1a7b4660984ce7e87a116873');
INSERT INTO `t_xiangmu` VALUES (37, '0001196-c82ab02c7b23424298aea4e3a83d1dc7', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', 0, NULL, '“医疗大数据分析平台建设”', '0000021-00000000000000000000000000000001', '建立医疗大数据分析平台，对海量医疗数据进行深度挖掘和分析，为医疗决策、疾病预防和治疗提供支持。', '0001199-5b49cc83be5e44e39d5f9572c0d17179');
INSERT INTO `t_xiangmu` VALUES (38, '0001196-8c90d2317bb441d097ae3182b1e32f46', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', 0, NULL, '“无人超市运营模式探索”', '0000021-00000000000000000000000000000001', '探索无人超市的运营模式和技术方案，实现超市的无人化经营，提高运营效率和顾客购物体验。', '0001199-ea5422fbf4c242bdb6d5cd7f926f93e3');
INSERT INTO `t_xiangmu` VALUES (39, '0001196-df288a6227a34ef78f31d59f4d0d8b5e', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', 0, NULL, '“城市公园生态修复工程”', '0000021-00000000000000000000000000000001', '对城市公园的生态环境进行修复和改善，增加植被覆盖，优化水体质量，打造生态友好型城市公园。', '0001199-9ce9636c83e34d9ea4805c6e4e8b0e0f');
INSERT INTO `t_xiangmu` VALUES (40, '0001196-2ef802b2a4b44c8bbbe05c6d934fee49', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', 0, NULL, '“个性化定制服装生产项目”', '0000021-00000000000000000000000000000001', '利用数字化技术实现服装的个性化定制生产，满足消费者对服装款式、尺寸和风格的个性化需求。', '0001199-5f44e017a4b74885a7f17cb98e5e4a19');
INSERT INTO `t_xiangmu` VALUES (41, '0001196-00f5df710e3e482990020ba80ef37cf7', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', 0, NULL, '“智能物流仓储管理系统开发”', '0000021-00000000000000000000000000000001', '开发一套智能物流仓储管理系统，实现货物的自动化存储、检索和管理，提高仓储空间利用率和作业效率。', '0001199-54b40c5fed8c4d93ba2b0b994c05a61d');
INSERT INTO `t_xiangmu` VALUES (42, '0001196-22dd6b9101364cd78c0903c67b43abf4', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', 0, NULL, '“农村电商人才培训计划”', '0000021-00000000000000000000000000000001', '针对农村地区开展电商人才培训，提高农民的电商运营能力，推动农村电商发展。', '0001199-35a72e0d8cc6458c9ece8eb8513291d1');
INSERT INTO `t_xiangmu` VALUES (43, '0001196-98002f73c1dc41a297ab1a9bdeaf9f11', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:43:59', '0000021-00000000000000000000000000000001', 0, NULL, '“太阳能光伏发电站建设”', '0000021-00000000000000000000000000000001', '在合适的地区建设太阳能光伏发电站，将太阳能转化为电能，并入电网供应。', '0001199-c15505d6a9134132bc27fbb9da78c11c');
INSERT INTO `t_xiangmu` VALUES (44, '0001196-2126ba80db094cab8f007f2115b5ff70', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', 0, NULL, '“智能语音助手应用拓展”', '0000021-00000000000000000000000000000001', '拓展智能语音助手的应用场景，如智能家居控制、办公辅助、车载系统等，提供更加便捷的人机交互方式。', '0001199-af5080ca81ab4fca9eca63207bcd5194');
INSERT INTO `t_xiangmu` VALUES (45, '0001196-26b484a37bdb46acb9faab6eb3fc788b', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', 0, NULL, '“海洋牧场建设与运营”', '0000021-00000000000000000000000000000001', '在海洋特定区域建设海洋牧场，进行海洋生物养殖和增殖，实现海洋渔业的可持续发展。', '0001199-cffb6a11c6674666ae37ec64990633aa');
INSERT INTO `t_xiangmu` VALUES (46, '0001196-c14dd0eb6f1b4d9aac7c5ff3dcb7098d', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', 0, NULL, '“金融科技风险防控系统研发”', '0000021-00000000000000000000000000000001', '研发针对金融科技领域的风险防控系统，有效识别和防范金融创新带来的各类风险。', '0001199-7a37c89645344ea2aac8314d7cdcf4d1');
INSERT INTO `t_xiangmu` VALUES (47, '0001196-21f1676031e94ba3aa4398659b68faaa', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', 0, NULL, '“智能垃圾分类与回收系统”', '0000021-00000000000000000000000000000001', '建立一套智能垃圾分类与回收系统，通过传感器和数据分析实现垃圾分类的自动化和精准化。', '0001199-c4fc8cf3b926484ab79e386e9ceac308');
INSERT INTO `t_xiangmu` VALUES (48, '0001196-094379ef1a714b708aed6a667d990234', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', 0, NULL, '“3D 打印医疗器械研发”', '0000021-00000000000000000000000000000001', '利用 3D 打印技术研发个性化的医疗器械，如假肢、牙齿矫正器等，提高医疗效果和患者舒适度。', '0001199-83b6231ba20141799186c87e9cea602b');
INSERT INTO `t_xiangmu` VALUES (49, '0001196-a0f25504ea9747dfa5a2ef48e238df18', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', 0, NULL, '“特色农产品品牌塑造”', '0000021-00000000000000000000000000000001', '对具有地域特色的农产品进行品牌策划和推广，提升农产品的附加值和市场竞争力。', '0001199-1abac97012424663b697b1bed6a58bf0');
INSERT INTO `t_xiangmu` VALUES (50, '0001196-7531830e573145d2a77dfef4a7e9050b', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', 0, NULL, '“智慧校园综合管理平台搭建”', '0000021-00000000000000000000000000000001', '搭建智慧校园综合管理平台，实现教学管理、学生管理、后勤管理等的信息化和智能化。', '0001199-c5063270004c45cf9ba2c8447a176946');
INSERT INTO `t_xiangmu` VALUES (51, '0001196-8dee2d7afc9141aa88c25aaa0b1afc4c', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', 0, NULL, '“工业机器人研发与应用”', '0000021-00000000000000000000000000000001', '研发高性能的工业机器人，并推动其在制造业中的广泛应用，提高生产效率和产品质量。', '0001199-f73343a6fc4640538478de6242633500');
INSERT INTO `t_xiangmu` VALUES (52, '0001196-f9ea6680bf0d4f68b94b01197bc93d34', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', 0, NULL, '“基因编辑技术治疗疾病研究”', '0000021-00000000000000000000000000000001', '开展基因编辑技术在疾病治疗方面的研究，探索治疗遗传疾病和疑难杂症的新方法。', '0001199-d20cdbf7df8c416c8f273472b33a24a8');
INSERT INTO `t_xiangmu` VALUES (53, '0001196-02fd214fc9074ce58fe5f9b4cfb24776', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:00', '0000021-00000000000000000000000000000001', 0, NULL, '“农村饮水安全提升工程”', '0000021-00000000000000000000000000000001', '对农村地区的饮水设施进行改造和升级，确保农村居民能够用上安全、清洁的饮用水。', '0001199-2a7a4a02464c470f82c216623c78a82f');
INSERT INTO `t_xiangmu` VALUES (54, '0001196-849e0b10c0b04403add8772cf28090c8', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', 0, NULL, '“无人配送机器人研发”', '0000021-00000000000000000000000000000001', '研发能够自主导航和送货的无人配送机器人，应用于快递、外卖等配送场景。', '0001199-54b40c5fed8c4d93ba2b0b994c05a61d');
INSERT INTO `t_xiangmu` VALUES (55, '0001196-9f5e5795c93f42a589ec68ddd54acdc8', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', 0, NULL, '“城市地下综合管廊建设”', '0000021-00000000000000000000000000000001', '在城市地下建设综合管廊，集中铺设电力、通信、给排水等各类管线，提高城市基础设施的管理和维护效率。', '0001199-35a72e0d8cc6458c9ece8eb8513291d1');
INSERT INTO `t_xiangmu` VALUES (56, '0001196-b37ead8f674a41e1bdc216fb6c740914', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', 0, NULL, '“量子通信技术应用试点”', '0000021-00000000000000000000000000000001', '开展量子通信技术在特定领域的应用试点，如金融、政务等，保障信息传输的安全性。', '0001199-c15505d6a9134132bc27fbb9da78c11c');
INSERT INTO `t_xiangmu` VALUES (57, '0001196-5f5ff477fa75482eae2a94d1b4b5f1b4', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', 0, NULL, '“中医药现代化研发项目”', '0000021-00000000000000000000000000000001', '运用现代科学技术对中医药进行研究和开发，提高中医药的疗效和质量控制水平。', '0001199-af5080ca81ab4fca9eca63207bcd5194');
INSERT INTO `t_xiangmu` VALUES (58, '0001196-6fc9a9d1a5b24ebfb31fda9bb21be89b', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', 0, NULL, '“航空航天零部件制造工艺改进”', '0000021-00000000000000000000000000000001', '改进航空航天零部件的制造工艺，提高零部件的精度和可靠性，满足航空航天领域的高要求。', '0001199-cffb6a11c6674666ae37ec64990633aa');
INSERT INTO `t_xiangmu` VALUES (59, '0001196-3e0bf7737b1e40388da69e395050a399', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', 0, NULL, '“智慧工厂建设方案”', '0000021-00000000000000000000000000000001', '打造智能化的工厂，实现生产设备的互联互通、生产过程的自动化控制和智能化管理。', '0001199-1abac97012424663b697b1bed6a58bf0');
INSERT INTO `t_xiangmu` VALUES (60, '0001196-8525fae3412b4ef297db335124bf1d53', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', 0, NULL, '“可穿戴健康监测设备研发”', '0000021-00000000000000000000000000000001', '研发具有多种健康监测功能的可穿戴设备，如心率监测、血压监测、睡眠监测等，为用户提供实时的健康数据。', '0001199-c5063270004c45cf9ba2c8447a176946');
INSERT INTO `t_xiangmu` VALUES (61, '0001196-1a88d847d616467a9a295573ce1de62d', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:01', '0000021-00000000000000000000000000000001', 0, NULL, '“文化创意产业园建设”', '0000021-00000000000000000000000000000001', '建设文化创意产业园，吸引文化创意企业入驻，形成产业集聚效应，推动文化创意产业发展。', '0001199-f73343a6fc4640538478de6242633500');
INSERT INTO `t_xiangmu` VALUES (62, '0001196-6b42a434a41849fb996917f8ee89222a', '2024-07-11 14:44:02', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:02', '0000021-00000000000000000000000000000001', 0, NULL, '“冷链物流配送优化”', '0000021-00000000000000000000000000000001', '优化冷链物流的配送流程和技术，确保生鲜食品、药品等在运输过程中的温度控制和质量安全。', '0001199-ecdec978734a444eae3d08a9a958f1fb');
INSERT INTO `t_xiangmu` VALUES (63, '0001196-876c749d7d064c6b95621bc194938352', '2024-07-11 14:44:02', '0000021-00000000000000000000000000000001', '0000021-00000000000000000000000000000001', '0000022-00000000000000000000000000000001', '2024-07-11 14:44:02', '0000021-00000000000000000000000000000001', 0, NULL, '“智慧水务管理系统开发”', '0000021-00000000000000000000000000000001', '开发智慧水务管理系统，实现对水资源的监测、调度和管理的智能化，提高水资源利用效率。', '0001199-b9ed3a0ecbcc491b8b816f76891b8fc0');
